export const TIERS_BY_LADDER = (ladder: 'history' | 'poem' | 'figure', cycle: LadderIdCycle = 1) =>
  [...HISTORY_TIERS, ...POEM_TIERS, ...FIGURE_TIERS].filter(t => t.ladder === ladder && t.cycle === cycle)

export const TIERS_BY_LADDER_ALL_CYCLES = (ladder: 'history' | 'poem' | 'figure') =>
  [...HISTORY_TIERS, ...POEM_TIERS, ...FIGURE_TIERS].filter(t => t.ladder === ladder)
